import com.sun.net.httpserver.HttpServer;
import java.io.OutputStream;
import java.lang.annotation.*;
import java.lang.reflect.*;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;

public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Get { String value(); }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.PARAMETER)
    @interface PathVar { String value(); }

    interface UserClient {
        @Get("/users/{id}")
        String getUser(@PathVar("id") int id);
    }

    record Instance(String baseUrl) {}

    interface RequestInterceptor {
        void apply(RequestTemplate template);
    }

    static final class RequestTemplate {
        final String method;
        String path;
        final Map<String, String> headers = new LinkedHashMap<>();

        RequestTemplate(String method, String path) {
            this.method = method;
            this.path = path;
        }
    }

    static final class MiniFeign {
        static <T> T create(Class<T> api, String serviceId, List<Instance> instances,
                            Duration timeout, List<RequestInterceptor> interceptors, T fallback) {
            HttpClient http = HttpClient.newBuilder().connectTimeout(timeout).build();
            InvocationHandler handler = (proxy, method, args) -> {
                if (method.getDeclaringClass() == Object.class) {
                    return switch (method.getName()) {
                        case "toString" -> "MiniFeign(" + serviceId + ")";
                        case "hashCode" -> System.identityHashCode(proxy);
                        case "equals" -> proxy == args[0];
                        default -> null;
                    };
                }
                try {
                    Get get = method.getAnnotation(Get.class);
                    if (get == null) {
                        throw new IllegalStateException("missing @Get on " + method.getName());
                    }
                    RequestTemplate template = new RequestTemplate("GET", get.value());
                    Annotation[][] parameterAnnotations = method.getParameterAnnotations();
                    for (int i = 0; i < parameterAnnotations.length; i++) {
                        for (Annotation annotation : parameterAnnotations[i]) {
                            if (annotation instanceof PathVar pathVar) {
                                String encoded = URLEncoder.encode(String.valueOf(args[i]), StandardCharsets.UTF_8);
                                template.path = template.path.replace("{" + pathVar.value() + "}", encoded);
                            }
                        }
                    }
                    for (RequestInterceptor interceptor : interceptors) {
                        interceptor.apply(template);
                    }
                    Instance instance = instances.get(0);
                    HttpRequest.Builder builder = HttpRequest.newBuilder()
                            .uri(URI.create(instance.baseUrl() + template.path))
                            .timeout(timeout)
                            .GET();
                    template.headers.forEach(builder::header);
                    HttpResponse<String> response = http.send(builder.build(), HttpResponse.BodyHandlers.ofString());
                    if (response.statusCode() >= 400) {
                        throw new IllegalStateException("http " + response.statusCode());
                    }
                    return response.body();
                } catch (Throwable failure) {
                    if (fallback != null) {
                        return method.invoke(fallback, args);
                    }
                    throw failure;
                }
            };
            Object proxy = Proxy.newProxyInstance(api.getClassLoader(), new Class<?>[]{api}, handler);
            return api.cast(proxy);
        }
    }

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(0), 0);
        server.createContext("/users/7", exchange -> {
            String trace = exchange.getRequestHeaders().getFirst("X-Trace-Id");
            String auth = exchange.getRequestHeaders().getFirst("Authorization");
            String body = "user=7,trace=" + trace + ",auth=" + auth;
            byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
            exchange.sendResponseHeaders(200, bytes.length);
            try (OutputStream out = exchange.getResponseBody()) {
                out.write(bytes);
            }
        });
        server.start();
        try {
            int port = server.getAddress().getPort();
            List<RequestInterceptor> interceptors = List.of(template -> {
                template.headers.put("Authorization", "Bearer demo");
                template.headers.put("X-Trace-Id", "trace-42");
            });
            UserClient client = MiniFeign.create(
                    UserClient.class,
                    "user-service",
                    List.of(new Instance("http://127.0.0.1:" + port)),
                    Duration.ofSeconds(2),
                    interceptors,
                    id -> "fallback:" + id
            );
            System.out.println(client.getUser(7));

            UserClient unavailable = MiniFeign.create(
                    UserClient.class,
                    "user-service",
                    List.of(new Instance("http://127.0.0.1:9")),
                    Duration.ofMillis(300),
                    List.of(),
                    id -> "fallback:" + id
            );
            System.out.println(unavailable.getUser(7));
        } finally {
            server.stop(0);
        }
    }
}
